&lt;li class=&quot;richTextDocs-listItem&quot; data-eleid=&quot;98405043-e11f-4830-a861-7b126729a55e-9-0&quot;&gt;
&lt;div class=&quot;richTextDocs-listItem__text&quot;&gt;&lt;span class=&quot;text-only&quot; data-eleid=&quot;98405043-e11f-4830-a861-7b126729a55e-9-0-0&quot;&gt;AI engineering mindset: understanding of LLM fundamentals, capability boundaries, and practical engineering usage&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;richTextDocs-listItem&quot; data-eleid=&quot;98405043-e11f-4830-a861-7b126729a55e-9-1&quot;&gt;
